@spec tv_fx_region_spec  src=tests/specs/tv_fx_region_spec.lua  loc=1500  cases=75
@exercises dataStore (h.ds), trackerManager (h.tm), midiManager (h.fm), trackerView (h.vm), editCursor (h.ec), commandManager (h.cmgr), clipboard (h.clipboard)
@surface   ds:assign, tm:rebuild, tm:addEvent, tm:flush, ds:get, fm:dump, vm:setGridSize, vm:ppqToRow, ec:setPos, vm:fxHostForEdit, vm:noteFx, vm:setNoteFx, vm:removeFxStage, vm:addFxStage, vm:setFxField, ec:setSelection, vm:rowToPPQ, vm:fxHostAtCursor, cmgr:invoke, tm:getChannel, vm:editEvent, tm:subscribe, ec:row, ec:extendTo, clipboard:collect, vm:ghostOverlay, tm:assignEvent, vm:addExtraCol
@harness   mk{seed.ccs}

# Intent
  Track B (note macros v2): the fx-region column + Super-X addressing. A region
  renders as a tailed kind-badge in a per-channel fx column, and the v1 note-FX
  editor addresses it by uuid. see design/note-macros-v2.md § Authoring and editing the fx

# Helpers
  @fn injectRegion(h, over)  @ 24-29
  @fn injectRegions(h, list)  @ 33-42
      -- Two producers, so a scoping case can ask which of them a ghost belongs to. Each entry
      -- overrides the defaults injectRegion uses; the uuid is positional ('fxr-1', 'fxr-2', ...).
  @fn noteAt(h, chan, ppq, pitch)  @ 44-48
  @fn fxColFor(h, chan)  @ 50-54
  @fn region(h, uuid)  @ 56-60
  @fn noteColIdx(h, chan, lane)  @ 62-66
  @fn ctsColIdx(h, chan, type, cc)  @ 68-72
  @fn addNote(h)  @ 74-78
  @fn authoredUuid(h)  @ 80-82
  @fn authoredPitches(h)  @ 86-93
      -- Pitches still sounding on the take (non-derived). Empty once a replace region has
      -- parked the covered chord off-take.

# Cases
  @case 'a region materialises a per-channel fx column with a badge + tail'  [harness]  @ 100-112
  @case 'a chain stacks its glyphs down the region rows in series order'  [harness]  @ 116-129
  @case 'a bypassed stage carries its flag down the stack'  [harness]  @ 133-143
  @case 'a chain longer than the region clips at the last row and marks it'  [harness]  @ 147-157
  @case 'a one-row region gives the clip mark the badge row'  [harness]  @ 161-169
  @case 'no region -> no fx column'  [harness]  @ 173-179
  @case 'an empty-fx region renders no column (it is an inert husk)'  [harness]  @ 183-189
  @case 'two overlapping regions pack into separate fx columns, each addressable'  [harness]  @ 195-223
  @case 'two disjoint regions share one fx column (packed into lane 1)'  [harness]  @ 227-239
  @case 'replace region: a parked note still renders in its note column'  [harness]  @ 245-257
  @case 'replace region: a parked cc still renders in its cc column'  [harness]  @ 261-284
  @case 'noteFx resolves a region uuid to its fx list'  [harness]  @ 290-295
  @case 'setNoteFx writes a region fx list back to ds'  [harness]  @ 299-305
  @case 'setNoteFx REMOVE deletes the region (a region is its fx)'  [harness]  @ 309-315
  @case 'region fx: deselecting the last kind keeps a husk the editor can repopulate'  [harness]  @ 319-329
  @case 'setFxField edits one region fx field, leaving the region'  [harness]  @ 333-339
  @case 'fxHostForEdit: caret on an fx cell returns the region uuid'  [harness]  @ 345-353
  @case 'fxHostForEdit: a selection mints a replace region over its span'  [harness]  @ 357-371
  @case 'fxHostAtCursor: a selection does not mint -- cursor movement has no side effect'  [harness]  @ 375-383
  @case 'fxHostAtCursor: caret anywhere in an fx region returns its uuid, nil past the tail'  [harness]  @ 387-400
  @case 'fxHostForEdit: off a note with no selection is nil; on a note, its uuid (v1)'  [harness]  @ 404-414
  @case 'parked note: a pitch nudge edits the off-take stash and re-renders, still parked'  [harness]  @ 420-434
  @case 'parked note: delete removes it from the stash and does not restore it when the window moves off'  [harness]  @ 438-449
  @case 'parked add: typing a note into a replace window stashes a logical spec, off the take'  [harness]  @ 453-467
  @case 'parked move-out: nudging a parked note past the window end restores it to the take'  [harness]  @ 471-484
  @case 'parked cc: a value nudge edits the off-take cc stash; delete removes it'  [harness]  @ 488-520
  @case 'parked pb: a value nudge edits the off-take pb stash; delete removes it'  [harness]  @ 524-560
  @case 'multi-select spanning a parked note and a take note: both edit under one rebuild'  [harness]  @ 564-585
  @case 'fx noteOff truncates the region tail to the cursor row'  [harness]  @ 591-603
  @case 'fx noteOff finds the right region in its lane when cells are in storage, not ppq, order'  [harness]  @ 607-621
  @case 'fx noteOff past the region tail grows it to the cursor row'  [harness]  @ 625-634
  @case 'fx noteOff on the onset row is a no-op (deletion is the delete verb, not noteOff)'  [harness]  @ 638-649
  @case 'fx noteOff on the window end row re-opens it to the pattern length'  [harness]  @ 653-663
  @case 'fx growNote / shrinkNote resize the region from its end'  [harness]  @ 667-678
  @case 'fx nudgeForward shifts the whole window and the caret follows'  [harness]  @ 682-694
  @case 'fx nudge keeps the moved region in its lane; the newly-overlapped sibling displaces right'  [harness]  @ 698-720
  @case 'fx nudge of an already-overlapping region keeps its own higher lane (no reorder)'  [harness]  @ 724-743
  @case 'fx nudge that makes an overlap disjoint tracks the caret across the column merge'  [harness]  @ 747-767
  @case 'fx window edit on a disjoint region does not churn storage order'  [harness]  @ 771-787
  @case 'fx nudgeBack refuses at the top grid edge (window unchanged)'  [harness]  @ 791-802
  @case 'fx eventShiftLeft swaps the region one lane left, flipping storage precedence'  [harness]  @ 808-832
  @case 'fx eventShiftRight swaps the region one lane right (the inverse move)'  [harness]  @ 836-851
  @case 'fx eventShift is a no-op at the grid edge (lone region, nothing beside it)'  [harness]  @ 855-867
  @case 'fx eventShift no-ops when the adjacent lane is empty at the cursor row'  [harness]  @ 871-886
  @case 'parked note: noteOff shortens its tail in the stash, stays parked'  [harness]  @ 892-905
  @case 'parked note: a time nudge within the window retimes the stash, stays parked'  [harness]  @ 909-922
  @case 'fx copy captures a region by onset; the whole window rides, tail spilling past the band'  [harness]  @ 928-946
  @case 'fx copy skips a region that only passes through the band (onset above it)'  [harness]  @ 950-959
  @case 'fx copy + paste stacks a duplicate region at the cursor row, original intact'  [harness]  @ 963-983
  @case 'fx delete removes the region under the caret'  [harness]  @ 987-996
  @case 'fx deleteSel drops every region the rectangle catches (onset in band), sparing the rest'  [harness]  @ 1000-1017
  @case 'fx freeze promotes the region output to authored notes and drops the region'  [harness]  @ 1023-1035
  @case 'fx freeze converts an fx-carrying note at the caret'  [harness]  @ 1039-1051
  @case 'fx freeze declines on a plain note (no chain to freeze)'  [harness]  @ 1055-1065
  @case 'fx freeze: a refused freeze opens no undo block; an eligible one opens exactly one'  [harness]  @ 1072-1109
  @case 'ghostOverlay: no host under the caret returns nil, before any window query'  [harness]  @ 1115-1123
  @case 'ghostOverlay: a host lights its derived onsets on the lane column, with pitch and vel'  [harness]  @ 1127-1153
  @case 'ghostOverlay: a host whose onsets lie outside the window answers empty, not nil'  [harness]  @ 1157-1169
  @case 'ghostOverlay: a row carrying a real cell still reports its ghost -- precedence is the draw arm\'s'  [harness]  @ 1173-1186
  @case 'ghostOverlay: the window is the viewport -- onsets below it are absent'  [harness]  @ 1190-1206
  @case 'ghostOverlay: a derived lane the channel does not carry shows nothing'  [harness]  @ 1211-1225
  @case 'ghostOverlay: the lanes the user authored take the rest of the voices'  [harness]  @ 1229-1244
  @case 'ghostOverlay: a pb chain lights its curve on the column the channel carries'  [harness]  @ 1250-1268
  @case 'ghostOverlay: only the claimed target lights -- an authored cc beside it stays dark'  [harness]  @ 1272-1285
  @case 'ghostOverlay: a kept producer still lights its curve after an edit elsewhere'  [harness]  @ 1289-1314
  @case 'ghostOverlay: a note host lights its continuous claim as a region does'  [harness]  @ 1318-1329
  @case 'ghostOverlay: adding the column by hand is what makes the claim visible'  [harness]  @ 1333-1350
  @case 'ghostOverlay: no host, no curve'  [harness]  @ 1354-1363
  @case 'ghostOverlay: a region host suppresses the parked chord it replaced, cells intact'  [harness]  @ 1369-1388
  @case 'ghostOverlay: the host\'s own parked cell stays visible'  [harness]  @ 1392-1407
  @case 'ghostOverlay: nothing on the take is ever suppressed'  [harness]  @ 1411-1421
  @case 'ghostOverlay: a chain on another channel keeps its ghosts to itself'  [harness]  @ 1427-1439
  @case 'ghostOverlay: a second chain further down the same channel stays dark'  [harness]  @ 1443-1458
  @case 'ghostOverlay: another chain's parked originals are not this one's to suppress'  [harness]  @ 1462-1479
  @case 'ghostOverlay: a second chain's curve claim does not light this one's column'  [harness]  @ 1483-1498

